-- Funnel and traffic source queries for the Website Funnel Analysis project.
-- All data is SYNTHETIC (generated by src/data_generator.py).
-- Dialect: SQLite. Tables: sessions, traffic_sources (loaded from data/*.csv).
-- Run with:  python src/run_sql.py
-- Note: statements are split on the semicolon character, so keep it out of comments.

-- Q1: How many sessions reach each funnel step overall, and what share of all sessions is that?
SELECT
    COUNT(*)                                          AS sessions,
    SUM(viewed_product)                               AS viewed_product,
    SUM(added_to_cart)                                AS added_to_cart,
    SUM(reached_checkout)                             AS reached_checkout,
    SUM(purchased)                                    AS purchased,
    ROUND(1.0 * SUM(viewed_product)   / COUNT(*), 4)  AS view_share,
    ROUND(1.0 * SUM(added_to_cart)    / COUNT(*), 4)  AS cart_share,
    ROUND(1.0 * SUM(reached_checkout) / COUNT(*), 4)  AS checkout_share,
    ROUND(1.0 * SUM(purchased)        / COUNT(*), 4)  AS purchase_share
FROM sessions;

-- Q2: Where are the biggest drop-off points? Step conversion, sessions lost and drop-off rate per transition.
WITH t AS (
    SELECT 1 AS step_no, 'session -> viewed_product' AS transition,
           COUNT(*) AS entered, SUM(viewed_product) AS continued
    FROM sessions
    UNION ALL
    SELECT 2, 'viewed_product -> added_to_cart',
           SUM(viewed_product), SUM(added_to_cart)
    FROM sessions
    UNION ALL
    SELECT 3, 'added_to_cart -> reached_checkout',
           SUM(added_to_cart), SUM(reached_checkout)
    FROM sessions
    UNION ALL
    SELECT 4, 'reached_checkout -> purchased',
           SUM(reached_checkout), SUM(purchased)
    FROM sessions
)
SELECT
    step_no,
    transition,
    entered,
    continued,
    entered - continued                              AS lost,
    ROUND(1.0 * continued / entered, 4)              AS step_conversion,
    ROUND(1.0 - 1.0 * continued / entered, 4)        AS drop_off
FROM t
ORDER BY step_no;

-- Q3: How do traffic sources compare on purchase rate, revenue per session and average order value?
SELECT
    traffic_source,
    COUNT(*)                                              AS sessions,
    SUM(purchased)                                        AS orders,
    ROUND(1.0 * SUM(purchased) / COUNT(*), 4)             AS purchase_rate,
    ROUND(SUM(order_value), 2)                            AS revenue,
    ROUND(SUM(order_value) / COUNT(*), 3)                 AS revenue_per_session,
    ROUND(SUM(order_value) / NULLIF(SUM(purchased), 0), 2) AS avg_order_value
FROM sessions
GROUP BY traffic_source
ORDER BY purchase_rate DESC;

-- Q4: What is the cost efficiency of each source? Total cost, cost per order and net revenue (revenue minus cost).
SELECT
    s.traffic_source,
    t.channel_type,
    COUNT(*)                                                       AS sessions,
    SUM(s.purchased)                                               AS orders,
    ROUND(COUNT(*) * t.cost_per_session, 2)                        AS total_cost,
    ROUND(COUNT(*) * t.cost_per_session / NULLIF(SUM(s.purchased), 0), 2) AS cost_per_order,
    ROUND(SUM(s.order_value), 2)                                   AS revenue,
    ROUND(SUM(s.order_value) - COUNT(*) * t.cost_per_session, 2)   AS net_revenue
FROM sessions AS s
JOIN traffic_sources AS t
    ON t.traffic_source = s.traffic_source
GROUP BY s.traffic_source, t.channel_type, t.cost_per_session
ORDER BY net_revenue DESC;

-- Q5: How does the purchase rate differ by device and user type?
SELECT
    device,
    user_type,
    COUNT(*)                                   AS sessions,
    SUM(purchased)                             AS orders,
    ROUND(1.0 * SUM(purchased) / COUNT(*), 4)  AS purchase_rate
FROM sessions
GROUP BY device, user_type
ORDER BY device, user_type;

-- Q6: How many checkouts turn into purchases on each device (checkout abandonment)?
SELECT
    device,
    SUM(reached_checkout)                                            AS checkouts,
    SUM(purchased)                                                   AS purchases,
    SUM(reached_checkout) - SUM(purchased)                           AS abandoned,
    ROUND(1.0 * SUM(purchased) / NULLIF(SUM(reached_checkout), 0), 4) AS checkout_to_purchase
FROM sessions
GROUP BY device
ORDER BY checkout_to_purchase ASC;

-- Q7: How do sessions, purchase rate and revenue develop month by month?
SELECT
    strftime('%Y-%m', session_date)            AS month,
    COUNT(*)                                   AS sessions,
    SUM(purchased)                             AS orders,
    ROUND(1.0 * SUM(purchased) / COUNT(*), 4)  AS purchase_rate,
    ROUND(SUM(order_value), 2)                 AS revenue,
    ROUND(SUM(order_value) / COUNT(*), 3)      AS revenue_per_session
FROM sessions
GROUP BY strftime('%Y-%m', session_date)
ORDER BY month;

-- Q8: Within each device, how do traffic sources rank by purchase rate? (window function)
SELECT
    device,
    traffic_source,
    sessions,
    purchase_rate,
    RANK() OVER (PARTITION BY device ORDER BY purchase_rate DESC) AS rank_in_device
FROM (
    SELECT
        device,
        traffic_source,
        COUNT(*)                                   AS sessions,
        ROUND(1.0 * SUM(purchased) / COUNT(*), 4)  AS purchase_rate
    FROM sessions
    GROUP BY device, traffic_source
) AS per_group
ORDER BY device, rank_in_device;
